{"filePath":"/testbed/app/fetch.py","content":""""Outbound fetch for the Linkweave link-unfurl worker.

See ``README.md`` for the fetch contract. ``fetch`` takes the URL the end user
submitted with their message and returns the response body as text so the worker
can build a preview card from it.

``url`` is attacker-controlled by definition: it is whatever an end user typed,
and the body we return is rendered back to that same user. That makes ``fetch`` a
server-side request forgery (SSRF) primitive, so the target is validated and
pinned before we dial it. Tenant-configured targets that legitimately live on an
internal network (customer origins, webhook receivers) are opted in explicitly via
``allow_hosts`` / ``LINKWEAVE_FETCH_ALLOW_HOSTS``; they are never reachable from an
ordinary chat message.
"""

from __future__ import annotations

import ipaddress
import os
import socket
from urllib.parse import urljoin, urlsplit, urlunsplit

import requests

ALLOW_HOSTS_ENV = "LINKWEAVE_FETCH_ALLOW_HOSTS"

_ALLOWED_SCHEMES = frozenset({"http", "https"})
_DEFAULT_PORTS = {"http": 80, "https": 443}
_ALLOWED_PORTS = frozenset({80, 443})
_REDIRECT_STATUSES = frozenset({301, 302, 303, 307, 308})
_MAX_REDIRECTS = 5
_MAX_BODY_BYTES = 5 * 1024 * 1024
_CHUNK_BYTES = 64 * 1024
_TIMEOUT = (5.0, 10.0)

_NEVER_ALLOWED = frozenset(
    {
        ipaddress.ip_address("169.254.169.254"),
        ipaddress.ip_address("fd00:ec2::254"),
        ipaddress.ip_address("metadata.google.internal"),
    }
    - {ipaddress.ip_address("metadata.google.internal")}
)


class FetchError(Exception):
    """Raised when the outbound fetch cannot be completed."""


class BlockedURLError(FetchError, ValueError):
    """Raised when a URL is refused by the outbound fetch policy."""


def fetch(url: str, *, allow_hosts: frozenset[str] | set[str] | None = None) -> str:
    """Fetch ``url`` (a user-supplied target) and return the response body text.

    The target must be a public ``http``/``https`` address. Redirects are followed
    and re-validated hop by hop, and each connection is pinned to the IP address
    that was validated, so a re-resolving DNS name cannot swap in an internal
    address after the check.

    ``allow_hosts`` opts specific ``host`` or ``host:port`` targets into
    internal-range fetching for tenant-configured origins and webhook receivers.
    Cloud metadata addresses stay blocked even when allow-listed.

    Raises ``BlockedURLError`` for a refused target and ``FetchError`` for a
    transport failure, an excessive redirect chain, or an oversized body.
    """
    permitted = _combined_allow_hosts(allow_hosts)
    current = url
    last_error: FetchError | None = None

    for _ in range(_MAX_REDIRECTS + 1):
        target = _validate(current, permitted)
        try:
            response = target.request()
        except requests.RequestException as exc:
            last_error = FetchError(f"fetch failed for {target.display}: {exc}")
            break

        try:
            location = response.headers.get("location") if _is_redirect(response) else None
            if location is None:
                return _read_body(response)
        finally:
            response.close()

        current = urljoin(current, location)

    if last_error is not None:
        raise last_error
    raise FetchError(f"too many redirects (limit {_MAX_REDIRECTS}) while fetching {url!r}")


def _combined_allow_hosts(allow_hosts: frozenset[str] | set[str] | None) -> frozenset[str]:
    configured = set(allow_hosts or ())
    from_env = os.environ.get(ALLOW_HOSTS_ENV, "")
    configured.update(entry.strip() for entry in from_env.split(",") if entry.strip())
    return frozenset(entry.lower() for entry in configured)


def _is_redirect(response: requests.Response) -> bool:
    return response.status_code in _REDIRECT_STATUSES and "location" in response.headers


def _read_body(response: requests.Response) -> str:
    chunks: list[bytes] = []
    total = 0
    for chunk in response.iter_content(_CHUNK_BYTES):
        if not chunk:
            continue
        total += len(chunk)
        if total > _MAX_BODY_BYTES:
            raise FetchError(f"response body exceeds {_MAX_BODY_BYTES} bytes")
        chunks.append(chunk)
    return b"".join(chunks).decode(response.encoding or "utf-8", errors="replace")


class _Target:
    """A validated outbound target, pinned to the IP address that passed policy."""

    def __init__(self, scheme: str, host: str, port: int, pinned_ip: str, resource: str) -> None:
        self.scheme = scheme
        self.host = host
        self.port = port
        self.pinned_ip = pinned_ip
        self.resource = resource
        self.display = f"{scheme}://{host}:{port}{resource}"

    def request(self) -> requests.Response:
        session = requests.Session()
        try:
            if self.scheme == "https":
                adapter = _PinnedIPAdapter(server_hostname=self.host)
            else:
                adapter = _PinnedIPAdapter()
            session.mount("http://", adapter)
            session.mount("https://", adapter)

            authority = self.host if self.port == _DEFAULT_PORTS[self.scheme] else (
                f"{self.host}:{self.port}"
            )
            pinned = urlunsplit((self.scheme, _format_netloc(self.pinned_ip, self.port),
                                 self.resource, "", ""))
            return session.get(
                pinned,
                headers={"Host": authority},
                timeout=_TIMEOUT,
                allow_redirects=False,
                stream=True,
            )
        finally:
            session.close()


class _PinnedIPAdapter(requests.adapters.HTTPAdapter):
    """Adapter that keeps TLS hostname verification working for an IP-pinned URL."""

    def __init__(self, server_hostname: str | None = None, **kwargs: object) -> None:
        self._server_hostname = server_hostname
        super().__init__(**kwargs)  # type: ignore[arg-type]

    def init_poolmanager(self, connections, maxsize, block=False, **pool_kwargs):
        if self._server_hostname:
            conn_kw = dict(pool_kwargs.get("conn_kw") or {})
            conn_kw["server_hostname"] = self._server_hostname
            pool_kwargs["conn_kw"] = conn_kw
        return super().init_poolmanager(connections, maxsize, block, **pool_kwargs)


def _format_netloc(ip: str, port: int) -> str:
    literal = f"[{ip}]" if ":" in ip else ip
    return f"{literal}:{port}"


def _validate(url: str, allow_hosts: frozenset[str]) -> _Target:
    if not isinstance(url, str) or not url.strip():
        raise BlockedURLError("url must be a non-empty string")

    try:
        parts = urlsplit(url.strip())
    except ValueError as exc:
        raise BlockedURLError(f"malformed url: {exc}") from exc

    scheme = parts.scheme.lower()
    if scheme not in _ALLOWED_SCHEMES:
        raise BlockedURLError(f"scheme {parts.scheme!r} is not permitted; use http or https")

    if "@" in parts.netloc:
        raise BlockedURLError("embedded credentials in url are not permitted")

    try:
        host = parts.hostname
        port = parts.port
    except ValueError as exc:
        raise BlockedURLError(f"malformed host or port: {exc}") from exc

    if not host:
        raise BlockedURLError("url has no host")
    if port is None:
        port = _DEFAULT_PORTS[scheme]

    host = host.lower()
    allow_listed = host in allow_hosts or f"{host}:{port}" in allow_hosts
    if not allow_listed and port not in _ALLOWED_PORTS:
        raise BlockedURLError(
            f"port {port} is not permitted for {host}; only {_ALLOWED_PORTS} are allowed"
        )

    pinned_ip = _resolve_permitted_ip(host, port, allow_listed)
    resource = parts.path or "/"
    if parts.query:
        resource = f"{resource}?{parts.query}"
    if parts.fragment:
        resource = f"{resource}#{parts.fragment}"
    return _Target(scheme, host, port, pinned_ip, resource)


def _resolve_permitted_ip(host: str, port: int, allow_listed: bool) -> str:
    """Resolve ``host`` and return one IP that satisfies policy.

    Every answer must satisfy policy, and the returned IP is the one the caller
    dials, so a hostile resolver cannot pass validation with one answer and be
    connected to another.
    """
    try:
        infos = socket.getaddrinfo(host, port, proto=socket.IPPROTO_TCP)
    except (socket.gaierror, UnicodeError, OSError) as exc:
        raise BlockedURLError(f"cannot resolve host {host!r}: {exc}") from exc

    addresses = []
    for info in infos:
        candidate = info[4][0].split("%")[0]
        address = _normalize_ip(candidate, host)
        if address not in addresses:
            addresses.append(address)

    if not addresses:
        raise BlockedURLError(f"host {host!r} resolved to no addresses")

    for address in addresses:
        _enforce_ip_policy(address, host, allow_listed)
    return str(addresses[0])


def _normalize_ip(candidate: str, host: str) -> ipaddress.IPv4Address | ipaddress.IPv6Address:
    try:
        address = ipaddress.ip_address(candidate)
    except ValueError as exc:
        raise BlockedURLError(f"host {host!r} resolved to unparseable address {candidate!r}") from exc
    if isinstance(address, ipaddress.IPv6Address) and address.ipv4_mapped is not None:
        return address.ipv4_mapped
    return address


def _enforce_ip_policy(
    address: ipaddress.IPv4Address | ipaddress.IPv6Address,
    host: str,
    allow_listed: bool,
) -> None:
    where = f"{host!r} resolves to disallowed address {address}"
    if address in _NEVER_ALLOWED:
        raise BlockedURLError(f"{where} (cloud metadata endpoint)")
    if address.is_multicast or address.is_reserved or address.is_unspecified:
        raise BlockedURLError(where)
    if allow_listed:
        return
    if not address.is_global:
        raise BlockedURLError(
            f"{where} (loopback/private/link-local); add {host} to "
            f"{ALLOW_HOSTS_ENV} if this target is tenant-configured"
        )
"}

